def compute(vars):
    high_price = vars["v1"]
    low_price = vars["v2"]
    fluctuation = high_price - low_price

    return {
        "value": fluctuation,
        "trace": {
            "high_price": high_price,
            "low_price": low_price,
            "fluctuation": fluctuation,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
